// AUTO-GENERATED from backend/src/data/verso-dataset (B_places + C_images).
// Regenerate from that folder rather than hand-editing.
//
// The prose here (name/description/tags) is authored in Uzbek only — the
// dataset never produced per-language versions of individual places the way
// it did for country-level summaries (see country-prose/). Price, hours and
// coordinates need no translation.
//
// 277 of 331 places carry a photograph (Wikimedia Commons, credited in
// the dataset's credits.csv), resized to 800px wide WebP and picked up by
// filename from ./global-place-images.
//
// The other 54 carry no image on purpose. Reviewing every photo against its
// place turned up dataset images that plainly show something else (a manhole
// cover for Pelourinho, a red door for the Pantanal, a bird sculpture for Oxford
// Street). A photograph of the wrong place is a false claim, so those fall back
// to the typographic plate until the dataset gets a correct image for them.
// at-hallstatt, az-flame-towers, de-neuschwanstein and gb-tower-bridge keep
// their original, verified images.

export interface GlobalPlace {
  id: string;
  name: string;
  type: "attraction" | "restaurant" | "hotel";
  city: string;
  countryCode: string;
  img?: string;
  description: string;
  price: string;
  priceUSD?: number;
  hours: string;
  transport: string;
  lat: number;
  lng: number;
  tags: string[];
}

const FILES = import.meta.glob("./global-place-images/*.webp", {
  eager: true,
  query: "?url",
  import: "default",
}) as Record<string, string>;

const img = (name: string): string | undefined => FILES[`./global-place-images/${name}.webp`];

