export const GLOBAL_PLACES_BY_COUNTRY: Map<string, GlobalPlace[]> = (() => {
  const m = new Map<string, GlobalPlace[]>();
  for (const p of GLOBAL_PLACES) {
    const list = m.get(p.countryCode) ?? [];
    list.push(p);
    m.set(p.countryCode, list);
  }
  return m;
})();
